<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class ProjectConfiguration extends Model { protected $fillable=['project_id','division_id','sub_division_id','tower_id','level_id','activity_id','sub_activity_id','apartment_id','typology_id','quantity','uom_id','priority']; protected $casts=['quantity'=>'float','priority'=>'integer']; public function project(){return $this->belongsTo(Project::class);} public function division(){return $this->belongsTo(Division::class);} public function subDivision(){return $this->belongsTo(SubDivision::class);} public function tower(){return $this->belongsTo(Tower::class);} public function level(){return $this->belongsTo(Level::class);} public function activity(){return $this->belongsTo(Activity::class);} public function subActivity(){return $this->belongsTo(SubActivity::class);} public function apartment(){return $this->belongsTo(Apartment::class);} public function typology(){return $this->belongsTo(ApartmentTypology::class,'typology_id');} public function uom(){return $this->belongsTo(Uom::class);} }
